mapper.select:
SELECT id, dialect, part_order, title, description, created_time, updated_time
FROM NC.study_part
WHERE id = #{id} AND dialect = #{dialect}

mapper.update:
UPDATE NC.study_part
SET part_order = #{partOrder}, title = #{title}, description = #{description}
WHERE id = #{id} AND dialect = #{dialect}

UPDATE NC.study_part
SET part_order = #{partOrder}
WHERE id = #{id} AND dialect = #{dialect}

mapper.delete:
DELETE FROM NC.study_part
WHERE id = #{id} AND dialect = #{dialect}
  AND NOT EXISTS (SELECT 1 FROM NC.study_chapter WHERE part_id = #{id})
